const V = SugarCube.State.variables;
const loc = V.location;
return JSON.stringify(Object.keys(loc||{}));

const out={};
const macs = SugarCube.Macro;
for (const nm of ['CityMap','createLocationButton','createSubLocationButton','UnlockLocation','createCityZone']) {
  try {
    const m = macs.get(nm);
    if (m && m.handler) out[nm]= m.handler.toString().slice(0,1800);
    else out[nm]='(not a registered macro)';
  } catch(e){ out[nm]='ERR '+e.message; }
}
return JSON.stringify(out);

const out={};
try { out.enterLocation = LocationService.enterLocation.toString().slice(0,2000); } catch(e){ out.enterLocation='ERR '+e.message; }
try { out.unlockLocation = LocationService.unlockLocation.toString().slice(0,1200); } catch(e){ out.unlockLocation='ERR '+e.message; }
try { out.handleSubLocation = (typeof handleSubLocation!=='undefined') ? handleSubLocation.toString().slice(0,1200) : '(global not found)'; } catch(e){ out.handleSubLocation='ERR '+e.message; }
return JSON.stringify(out);

const found=[];
const roots={window:window, setup:setup};
for (const rn in roots){ const r=roots[rn]; if(!r) continue;
  for (const k in r){ try{ if(/Location/i.test(k)) found.push(rn+'.'+k+' :: '+typeof r[k]); }catch(e){} }
}
// also check window.LocationService directly + common module holders
let svc = window.LocationService || (window.setup&&setup.LocationService) || (window.Game&&Game.LocationService);
return JSON.stringify({found, hasWindowLS: typeof window.LocationService, svcType: typeof svc});

var found=[];
for (var k in window){ try{ if(/Location|Service/i.test(k)) found.push(k+':'+typeof window[k]); }catch(e){} }
for (var k2 in setup){ try{ if(/Location|Service/i.test(k2)) found.push('setup.'+k2+':'+typeof setup[k2]); }catch(e){} }
return found.join(' | ');

var hits=[];
for (var k in window){ try{ if(/Location|Service/i.test(k)) hits.push(k+':'+typeof window[k]); }catch(e){} }
var ls = window.LocationService;
var src='';
if (ls && ls.enterLocation) src = ls.enterLocation.toString().slice(0,1500);
return JSON.stringify({hits:hits, lsType: typeof ls, enterSrc: src});

var out={};
try{ out.getLocationPassage = getLocationPassage.toString().slice(0,1200);}catch(e){out.getLocationPassage='ERR';}
try{ out.GameLocationKeys = Object.keys(GameLocation).slice(0,30);}catch(e){out.GameLocationKeys='ERR '+e.message;}
return JSON.stringify(out);

var c = document.querySelector('.gridcityZone-container');
if(!c) return 'NO container';
var tiles=[];
c.querySelectorAll('.image-wrapper').forEach(function(w){
  var title=(w.querySelector('span')||{}).textContent||'';
  var closed=w.querySelector('.closed-label')?('CLOSED '+((w.querySelector('.closed-opens-at')||{}).textContent||'')):'open';
  tiles.push(title.trim()+' -> '+closed);
});
return JSON.stringify(tiles);

var tiles=[];
document.querySelectorAll('.image-wrapper').forEach(function(w){
  var title=(w.querySelector('span')||{}).textContent||'';
  var closed=w.querySelector('.closed-label')?('CLOSED '+((w.querySelector('.closed-opens-at')||{}).textContent||'')):'';
  tiles.push(title.trim()+(closed?(' ['+closed.trim()+']'):''));
});
return JSON.stringify(tiles);

var tiles=[];
document.querySelectorAll('.image-wrapper').forEach(function(w){
  var title=(w.querySelector('span')||{}).textContent||'';
  var lbl=w.querySelector('.closed-label');
  var oa=w.querySelector('.closed-opens-at');
  var closed=lbl?(' ['+lbl.textContent.trim()+(oa?(' / '+oa.textContent.trim()):'')+']'):'';
  tiles.push(title.trim()+closed);
});
return JSON.stringify(tiles);

var before = SugarCube.State.passage;
var target=null;
document.querySelectorAll('.image-wrapper').forEach(function(w){
  var t=(w.querySelector('span')||{}).textContent||'';
  if(/Night Club/i.test(t)) target=w.querySelector('a');
});
if(!target) return 'no club tile';
target.click();
return 'clicked Night Club (closed). before='+before;

var tiles=[];
document.querySelectorAll('.image-wrapper').forEach(function(w){
  var t=(w.querySelector('span')||{}).textContent||'';
  var lbl=w.querySelector('.closed-label');
  tiles.push(t.trim()+(lbl?' [CLOSED]':''));
});
return JSON.stringify(tiles);
